#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <format>
#include <iostream>

using namespace std::chrono_literals;

struct State {
  double position_m;
  double velocity_mps;
};

// A slider held at 0 by a position controller that pushes with -gain * position.
struct Plant {
  double mass_kg;
  double gain_n_per_m;
};

// One fixed step of semi-implicit Euler: velocity first, then position with the new velocity.
[[nodiscard]] State step(State s, Plant p, std::chrono::nanoseconds dt) {
  const double h = std::chrono::duration<double>(dt).count();
  s.velocity_mps += -p.gain_n_per_m * s.position_m / p.mass_kg * h;
  s.position_m += s.velocity_mps * h;
  return s;
}

struct Run {
  State end;
  double peak_m;
  std::int64_t steps;
};

// Simulated time is an integer count of nanoseconds, as in Gazebo, so the number of steps is exact.
[[nodiscard]] Run simulate(Plant p, State start, std::chrono::nanoseconds dt, std::chrono::nanoseconds duration) {
  Run r{.end = start, .peak_m = std::abs(start.position_m), .steps = 0};
  for (std::chrono::nanoseconds t{0}; t < duration; t += dt) {
    r.end = step(r.end, p, dt);
    r.peak_m = std::max(r.peak_m, std::abs(r.end.position_m));
    ++r.steps;
  }
  return r;
}

int main() {
  constexpr Plant slider{.mass_kg = 1.0, .gain_n_per_m = 10'000.0};
  constexpr State start{.position_m = 0.1, .velocity_mps = 0.0};
  for (const std::chrono::milliseconds dt : std::array{1ms, 5ms, 10ms, 20ms, 25ms}) {
    const Run r = simulate(slider, start, dt, 2s);
    if (r.peak_m < 1.0) {
      std::cout << std::format("step {:>4}: {:4} steps, x(2 s) = {:+.4f} m\n", dt, r.steps, r.end.position_m);
    } else {
      std::cout << std::format("step {:>4}: {:4} steps, unstable, peak {:.3g} m\n", dt, r.steps, r.peak_m);
    }
  }
  std::cout << std::format("exact:                  x(2 s) = {:+.4f} m\n", 0.1 * std::cos(200.0));

  const Run a = simulate(slider, start, 1ms, 2s);
  const Run b = simulate(slider, start, 1ms, 2s);
  const bool same = a.end.position_m == b.end.position_m && a.end.velocity_mps == b.end.velocity_mps;
  std::cout << std::format("two runs at 1 ms end in identical bits: {}\n", same);

  std::int64_t double_steps = 0;
  for (double t = 0.0; t < 2.0; t += 0.001) ++double_steps;
  std::cout << std::format("a double time counter takes {} steps of 1 ms to reach 2 s\n", double_steps);
}
